    const auto& p = points[i];
    if (p.x >= range.Min.x && p.x <= range.Max.x &&
        p.y >= range.Min.y && p.y <= range.Max.y &&
        p.z >= range.Min.z && p.z <= range.Max.z) {
        indices.push_back(i);
    }
}
return indices;

